/* Phaser 4.2.1 owns rendering, texture cache, input and visual feedback.
   model.js owns world coordinates, targeting, damage, wave timing and economy. */
(function(){'use strict';const F=Forest;
class ForestScene extends Phaser.Scene{
constructor(){super('forest');}
preload(){this.load.on('progress',v=>{document.getElementById('loadBar').style.width=(v*100)+'%'});this.load.on('loaderror',f=>{document.getElementById('loadText').textContent='素材讀取失敗：'+f.key+'，請重新整理';});for(const id of ['bow','fire'])for(let i=0;i<5;i++)this.load.image(id+i,`assets/${id}-${i}.webp`);for(const i of [0,1,2,5])this.load.image('enemy'+i,`assets/monsters-${i}.webp`);for(const [key,file]of [['forest','forest.webp'],['earth','earth.webp'],['castle','castle-0.webp'],['portal','portal.webp']])this.load.image(key,'assets/'+file);}
create(){this.model=new F.Game;this.selected=-1;this.playing=false;this.ambient=0;this.enemyViews=new Map;this.towerViews=new Map;this.effects=[];this.background=this.add.image(0,0,'forest');this.world=this.add.container(0,0);this.makeRoad();this.road=this.add.image(0,0,'road').setOrigin(0);this.world.add(this.road);this.range=this.add.graphics();this.world.add(this.range);this.padViews=[];
F.PADS.forEach(([x,y],i)=>{const g=this.add.graphics();g.fillStyle(0x274b34,.15).fillEllipse(x,y+9,79,29);g.fillStyle(0xdce0b2,.8).fillEllipse(x,y,77,30);g.lineStyle(1.5,0x849a61,.7).strokeEllipse(x,y,77,30);g.lineStyle(1,0xf8f2cc,.8).strokeEllipse(x,y-1,65,23);g.lineStyle(2.5,0x648b59,.8).lineBetween(x-6,y,x+6,y).lineBetween(x,y-6,x,y+6);this.world.add(g);this.padViews.push(g);const z=this.add.zone(x,y-18,108,95).setInteractive({useHandCursor:true});this.world.add(z);z.on('pointerdown',()=>{if(this.playing)window.UI?.select(i);});});
this.shadowLayer=this.add.graphics();this.world.add(this.shadowLayer);this.creatures=this.add.container(0,0);this.world.add(this.creatures);const portal=this.add.image(95,245,'portal').setOrigin(.5,1).setDisplaySize(76,82);const castle=this.add.image(1170,319,'castle').setOrigin(.5,1).setDisplaySize(119,132);this.creatures.add([portal,castle]);this.portal=portal;this.castle=castle;this.projectile=this.add.graphics();this.world.add(this.projectile);this.effectLayer=this.add.container(0,0);this.world.add(this.effectLayer);this.leaves=this.add.graphics();this.world.add(this.leaves);this.layout();this.scale.on('resize',()=>this.layout());document.getElementById('loader').hidden=true;window.battle=this;window.dispatchEvent(new Event('forest-ready'));}
makeRoad(){const c=document.createElement('canvas');c.width=1280;c.height=440;const x=c.getContext('2d'),p=new Path2D;p.moveTo(...F.ROUTE[0]);for(const a of F.ROUTE.slice(1))p.lineTo(...a);x.lineJoin='round';x.lineCap='round';x.strokeStyle='#3e4e3028';x.lineWidth=56;x.stroke(p);x.strokeStyle='#72854770';x.lineWidth=48;x.stroke(p);x.strokeStyle=x.createPattern(this.textures.get('earth').getSourceImage(),'repeat');x.lineWidth=43;x.stroke(p);x.strokeStyle='#edcf9929';x.lineWidth=27;x.stroke(p);let seed=101;const rand=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);for(let j=1;j<F.ROUTE.length;j++){const a=F.ROUTE[j-1],b=F.ROUTE[j],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy),nx=-dy/len,ny=dx/len;for(let d=10;d<len-7;d+=7+rand()*13){for(const side of [-1,1]){const xx=a[0]+dx*d/len+nx*(22+rand()*5)*side,yy=a[1]+dy*d/len+ny*(22+rand()*5)*side;x.fillStyle=rand()>.5?'#6f874d':'#b1af74';x.beginPath();x.ellipse(xx,yy,1.5+rand()*2,1+rand(),rand()*3,0,7);x.fill();if(rand()>.45){x.strokeStyle='#6a8747aa';x.lineWidth=1.1;x.beginPath();x.moveTo(xx-2,yy-2);x.lineTo(xx,yy+1);x.lineTo(xx+2,yy-4);x.stroke();}}}if(j%2===1){x.strokeStyle='#537f6470';x.lineWidth=2;x.beginPath();const mx=(a[0]+b[0])/2,my=(a[1]+b[1])/2;x.moveTo(mx-dx/len*4+nx*4,my-dy/len*4+ny*4);x.lineTo(mx+dx/len*3,my+dy/len*3);x.lineTo(mx-dx/len*4-nx*4,my-dy/len*4-ny*4);x.stroke();}}
this.textures.addCanvas('road',c);}
layout(){const w=this.scale.width,h=this.scale.height;const size=this.textures.get('forest').getSourceImage();const cover=Math.max(w/size.width,h/size.height);this.background.setPosition(w/2,h/2).setScale(cover);const top=h<500?78:123,bottom=h<500?80:110;this.worldScale=Math.min((w-62)/1280,(h-top-bottom)/400);this.worldScale=Math.max(.1,this.worldScale);this.world.setScale(this.worldScale).setPosition((w-1280*this.worldScale)/2,top+(h-top-bottom-400*this.worldScale)/2);window.UI?.layout?.();}
reset(){this.model=new F.Game;for(const v of this.enemyViews.values())v.destroy();for(const v of this.towerViews.values())v.destroy();this.enemyViews.clear();this.towerViews.clear();this.effectLayer.removeAll(true);this.projectile.clear();this.selected=-1;this.padViews.forEach(v=>v.setVisible(true));this.drawRange();this.syncShadows();}
select(i){this.selected=i;this.drawRange();}
drawRange(previewType){this.range.clear();if(this.selected<0)return;const [x,y]=F.PADS[this.selected],t=this.model.towers.find(t=>t.pad===this.selected);if(!t&&previewType===undefined)return;const r=t?F.stats(t).range:F.stats({type:previewType,level:1,branch:-1}).range;this.range.fillStyle(0xb8e1b1,.08).fillCircle(x,y,r);this.range.lineStyle(2.5,0xf9e5a3,.9).strokeCircle(x,y,r);this.range.lineStyle(1,0xffffff,.6).strokeCircle(x,y,r-5);this.range.lineStyle(2,0xf5df8f,.9).strokeEllipse(x,y+2,89,35);}
addTower(t){const im=this.add.image(t.x,t.y+17,F.TOWERS[t.type].id+F.variant(t)).setOrigin(.5,1);this.creatures.add(im);this.towerViews.set(t.id,im);this.sizeTower(t,im);im.setScale(im.scaleX*.72,im.scaleY*.72);this.tweens.add({targets:im,scaleX:im.baseScale,scaleY:im.baseScale,duration:350,ease:'Back.Out'});this.padViews[t.pad].setVisible(false);this.burst(t.x,t.y,0xe7d48b,12,40);this.syncShadows();}
sizeTower(t,im){im.setTexture(F.TOWERS[t.type].id+F.variant(t));const width=t.level>=5?146:t.level>=2?132:118;im.baseScale=width/im.width;im.setScale(im.baseScale);}
syncShadows(){this.shadowLayer.clear();for(const t of this.model.towers){this.shadowLayer.fillStyle(0x284c32,.22).fillEllipse(t.x+2,t.y+10,t.level===5?96:80,24);this.shadowLayer.fillStyle(0x24402c,.14).fillEllipse(t.x,t.y+8,58,15);}}
burst(x,y,color,count=7,radius=24){if(this.effectLayer.length>160)return;for(let i=0;i<count;i++){const a=Math.PI*2*i/count+Math.random()*.5,r=radius*(.5+Math.random()*.5);const p=this.add.circle(x,y,2+Math.random()*2,color,.9);this.effectLayer.add(p);this.tweens.add({targets:p,x:x+Math.cos(a)*r,y:y+Math.sin(a)*r-9,alpha:0,scale:0,duration:360+Math.random()*250,ease:'Quad.Out',onComplete:()=>p.destroy()});}}
ring(x,y,color,r=60){const c=this.add.circle(x,y,5,color,.12).setStrokeStyle(2,color,.9);this.effectLayer.add(c);this.tweens.add({targets:c,scale:r/5,alpha:0,duration:440,ease:'Cubic.Out',onComplete:()=>c.destroy()});}
float(x,y,str,color='#fff1b9'){if(this.effectLayer.length>160)return;const t=this.add.text(x,y,str,{fontFamily:'system-ui',fontSize:16,fontStyle:'bold',color,stroke:'#34523a',strokeThickness:3}).setOrigin(.5);this.effectLayer.add(t);this.tweens.add({targets:t,y:y-37,alpha:0,duration:800,ease:'Quad.Out',onComplete:()=>t.destroy()});}
process(){for(const e of this.model.drain()){switch(e.type){case'build':this.addTower(e.tower);break;case'upgrade':{const v=this.towerViews.get(e.tower.id);this.sizeTower(e.tower,v);this.ring(e.tower.x,e.tower.y,0xf3d77e,80);this.burst(e.tower.x,e.tower.y-45,0xfbe8a0,18,70);this.float(e.tower.x,e.tower.y-90,'Lv.'+e.tower.level);this.syncShadows();this.drawRange();break;}case'sell':this.towerViews.get(e.tower.id)?.destroy();this.towerViews.delete(e.tower.id);this.padViews[e.tower.pad].setVisible(true);this.float(e.tower.x,e.tower.y,'+'+e.gold);this.syncShadows();break;case'spawn':{const v=this.add.container(e.enemy.x,e.enemy.y);const d=F.ENEMIES[e.enemy.type],w=e.enemy.type===3?89:55,im=this.add.image(0,4,'enemy'+d.art).setOrigin(.5,1);im.setScale(w/im.width);im.baseScale=im.scaleX;const bar=this.add.graphics();v.add([im,bar]);v.body=im;v.bar=bar;this.creatures.add(v);this.enemyViews.set(e.enemy.id,v);break;}case'fire':{const v=this.towerViews.get(e.tower.id);if(v){this.tweens.killTweensOf(v);v.setScale(v.baseScale*1.025,v.baseScale*.975);this.tweens.add({targets:v,scaleX:v.baseScale,scaleY:v.baseScale,duration:150});}this.burst(e.shot.x,e.shot.y,e.tower.type?0xffc469:0xc0dfa0,3,12);window.UI?.sound(e.tower.type?'fire':'arrow');break;}case'hit':{const v=this.enemyViews.get(e.enemy.id);if(v&&e.damage>1){v.body.setTint(0xffe5b4);this.time.delayedCall(70,()=>{if(v.active)v.body.clearTint();});}break;}case'kill':{this.burst(e.enemy.x,e.enemy.y-15,0xe5d59a,6,24);this.float(e.enemy.x,e.enemy.y-35,'+'+e.gold);break;}case'impact':if(e.shot.type){const color=e.shot.branch===1?0xe66f39:0xffc35e;this.ring(e.shot.tx,e.shot.ty,color,e.shot.stats.splash);this.burst(e.shot.tx,e.shot.ty-8,color,e.shot.final?16:9,e.shot.stats.splash*.7);}else this.burst(e.shot.tx,e.shot.ty-15,e.shot.branch===1?0xb6d8ff:0xdbeda2,4,16);break;case'leak':this.ring(1170,298,0xd58677,80);this.float(1170,210,'−'+e.enemy.leak,'#ffc3ac');window.UI?.sound('leak');break;}
window.UI?.event(e);}}
update(time,delta){if(!this.model)return;this.world.setVisible(this.playing);this.ambient=time/1000;this.tweens.timeScale=this.model.paused?0:this.model.speed;this.model.step(Math.min(delta/1000,.05));this.process();for(const [id,v]of this.enemyViews){const e=this.model.enemies.find(e=>e.id===id);if(!e){v.destroy();this.enemyViews.delete(id);continue;}v.setPosition(e.x,e.y);const im=v.body,pulse=Math.sin(this.ambient*7+id)*.035;im.setScale(im.baseScale*(1-pulse),im.baseScale*(1+pulse));v.bar.clear();if(e.hp<e.maxHp){v.bar.fillStyle(0x25422f,.7).fillRoundedRect(-20,-im.displayHeight-6,40,4,2);v.bar.fillStyle(e.burnTime>0?0xe9aa55:0xa8c774,1).fillRoundedRect(-20,-im.displayHeight-6,40*e.hp/e.maxHp,4,2);}if(e.burnTime>0&&Math.random()<.07)this.burst(e.x,e.y-15,0xee9c48,1,7);}
this.creatures.list.sort((a,b)=>a.y-b.y);this.projectile.clear();for(const p of this.model.shots){const q=Math.min(1,p.time/p.duration);let tx=p.tx,ty=p.ty;if(!p.type){const target=this.model.enemies.find(e=>e.id===p.target);if(target){tx=target.x;ty=target.y-15;}}const x=p.x+(tx-p.x)*q,y=p.y+(ty-p.y)*q-(p.type?Math.sin(q*Math.PI)*75:0);if(p.type){this.projectile.fillStyle(0xffc25c,.16).fillCircle(x,y,p.final?21:15);this.projectile.fillStyle(p.branch===1?0xe5632d:0xffa441,.75).fillCircle(x,y,9);this.projectile.fillStyle(0xffefad,1).fillCircle(x-2,y-2,5);this.projectile.lineStyle(2,0xffd07b,.4).lineBetween(x-9,y-7,x-20,y-18);}else{const a=Math.atan2(ty-p.y,tx-p.x),dx=Math.cos(a),dy=Math.sin(a),len=p.branch===1?27:18;this.projectile.lineStyle(p.final?4:2.5,p.branch===1?0xb8d7ff:0xffefb8,.9).lineBetween(x-dx*len,y-dy*len,x,y);this.projectile.lineStyle(2,0xfef9da,1).lineBetween(x-dx*7+dy*4,y-dy*7-dx*4,x,y).lineBetween(x,y,x-dx*7-dy*4,y-dy*7+dx*4);}}
this.leaves.clear();for(let i=0;i<12;i++){const t=this.ambient*.2+i*1.7,x=(i*127+t*17)%1280,y=25+(i*73+t*6)%360;this.leaves.fillStyle(i%3?0xc4dc76:0xf7e7a5,.25+.18*Math.sin(t+i)).fillEllipse(x,y,4+i%3,2);}if(this.playing)window.UI?.frame();}
}
window.ForestScene=ForestScene;window.phaserGame=new Phaser.Game({type:Phaser.AUTO,parent:'game',backgroundColor:'#466b40',scale:{mode:Phaser.Scale.RESIZE,width:window.innerWidth,height:window.innerHeight},render:{antialias:true,roundPixels:false},resolution:Math.min(window.devicePixelRatio||1,2),scene:[ForestScene],audio:{noAudio:true},fps:{target:60}});
})();
